// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Create an administrator browser session
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the current administrator browser session
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ChangeAdministratorPassword Replace the sole administrator password and revoke all sessions
	// (PUT /api/v1/auth/password)
	ChangeAdministratorPassword(w http.ResponseWriter, r *http.Request)
	// GetAuthSession Read the current administrator browser session
	// (GET /api/v1/auth/session)
	GetAuthSession(w http.ResponseWriter, r *http.Request)
	// ListCalls List Simulator call records
	// (GET /api/v1/calls)
	ListCalls(w http.ResponseWriter, r *http.Request)
	// DialCall Dial in the Simulator call state machine
	// (POST /api/v1/calls/dial)
	DialCall(w http.ResponseWriter, r *http.Request)
	// SimulateIncomingCall Inject a Simulator incoming call
	// (POST /api/v1/calls/incoming)
	SimulateIncomingCall(w http.ResponseWriter, r *http.Request)
	// ControlCall Answer, reject, hang up, or send DTMF in Simulator
	// (POST /api/v1/calls/{callId}/action)
	ControlCall(w http.ResponseWriter, r *http.Request, callId string)
	// ListContacts List durable contacts
	// (GET /api/v1/contacts)
	ListContacts(w http.ResponseWriter, r *http.Request)
	// CreateContact Create a contact
	// (POST /api/v1/contacts)
	CreateContact(w http.ResponseWriter, r *http.Request)
	// DeleteContact Delete a contact
	// (DELETE /api/v1/contacts/{contactId})
	DeleteContact(w http.ResponseWriter, r *http.Request, contactId string)
	// UpdateContact Update a contact
	// (PUT /api/v1/contacts/{contactId})
	UpdateContact(w http.ResponseWriter, r *http.Request, contactId string)
	// GetEUICCState Read Simulator removable-eUICC installed profiles
	// (GET /api/v1/euicc)
	GetEUICCState(w http.ResponseWriter, r *http.Request)
	// ActivateEUICCProfile Switch active profile in Simulator and read back confirmation
	// (POST /api/v1/euicc/profiles/{profileId}/activate)
	ActivateEUICCProfile(w http.ResponseWriter, r *http.Request, profileId string)
	// GetHardwareTopology Read the normalized dynamic hardware, SIM, Profile, ResourceGroup, and Line graph
	// (GET /api/v1/hardware/topology)
	GetHardwareTopology(w http.ResponseWriter, r *http.Request)
	// GetInventory Read the discovered device and active-line inventory
	// (GET /api/v1/inventory)
	GetInventory(w http.ResponseWriter, r *http.Request)
	// ListLineCandidates List current Line candidates and typed readiness for every administrator-added modem
	// (GET /api/v1/line-candidates)
	ListLineCandidates(w http.ResponseWriter, r *http.Request)
	// ListLineEgressBindings List explicit direct, Mihomo-country, or unconfigured egress state for current Lines
	// (GET /api/v1/line-egress-bindings)
	ListLineEgressBindings(w http.ResponseWriter, r *http.Request)
	// ListManagedLines List administrator-created Lines and their resolved runtime state
	// (GET /api/v1/lines)
	ListManagedLines(w http.ResponseWriter, r *http.Request)
	// AddManagedLine Create only a stable Line identity from one current managed-modem SIM/Profile candidate
	// (POST /api/v1/lines)
	AddManagedLine(w http.ResponseWriter, r *http.Request)
	// UpdateManagedLine Update a Line display name without rebinding hardware
	// (PUT /api/v1/lines/{lineId})
	UpdateManagedLine(w http.ResponseWriter, r *http.Request, lineId string)
	// PutLineEgressBinding Persist an explicit direct or Mihomo-country Line egress choice without rewriting or restarting Mihomo
	// (PUT /api/v1/lines/{lineId}/egress)
	PutLineEgressBinding(w http.ResponseWriter, r *http.Request, lineId string)
	// ListMessages List the most recent durable SMS records
	// (GET /api/v1/messages)
	ListMessages(w http.ResponseWriter, r *http.Request)
	// SendMessage Persist and send one SMS on a selected line
	// (POST /api/v1/messages)
	SendMessage(w http.ResponseWriter, r *http.Request)
	// DeleteMessage Delete one SMS record from the application database
	// (DELETE /api/v1/messages/{messageId})
	DeleteMessage(w http.ResponseWriter, r *http.Request, messageId string)
	// GetMihomoConfigStatus Read generated configuration status without starting Mihomo
	// (GET /api/v1/mihomo/config)
	GetMihomoConfigStatus(w http.ResponseWriter, r *http.Request)
	// PublishMihomoConfig Generate, validate, and atomically publish configuration without starting Mihomo
	// (POST /api/v1/mihomo/config)
	PublishMihomoConfig(w http.ResponseWriter, r *http.Request)
	// GetMihomoCoreStatus Read the locally installed Mihomo core status
	// (GET /api/v1/mihomo/core)
	GetMihomoCoreStatus(w http.ResponseWriter, r *http.Request)
	// InstallLatestMihomoCore Download, verify, probe, and atomically install the latest official stable core
	// (POST /api/v1/mihomo/core/install)
	InstallLatestMihomoCore(w http.ResponseWriter, r *http.Request)
	// GetLatestMihomoCore Check the official MetaCubeX stable release
	// (GET /api/v1/mihomo/core/latest)
	GetLatestMihomoCore(w http.ResponseWriter, r *http.Request)
	// GetMihomoDashboardStatus Read the installed Zashboard entry point and Mihomo controller credentials
	// (GET /api/v1/mihomo/dashboard)
	GetMihomoDashboardStatus(w http.ResponseWriter, r *http.Request)
	// GetMihomoRuntimeStatus Read Mihomo process state and selected/running subscription distinction
	// (GET /api/v1/mihomo/runtime)
	GetMihomoRuntimeStatus(w http.ResponseWriter, r *http.Request)
	// RestartMihomo Revalidate selected artifact and restart Mihomo to apply it
	// (POST /api/v1/mihomo/runtime/restart)
	RestartMihomo(w http.ResponseWriter, r *http.Request)
	// StartMihomo Start Mihomo with the currently selected and revalidated subscription artifact
	// (POST /api/v1/mihomo/runtime/start)
	StartMihomo(w http.ResponseWriter, r *http.Request)
	// StopMihomo Stop the managed Mihomo process
	// (POST /api/v1/mihomo/runtime/stop)
	StopMihomo(w http.ResponseWriter, r *http.Request)
	// ListMihomoSubscriptions List subscriptions including their plaintext URLs
	// (GET /api/v1/mihomo/subscriptions)
	ListMihomoSubscriptions(w http.ResponseWriter, r *http.Request)
	// CreateMihomoSubscription Store a plaintext HTTPS subscription URL in the private database
	// (POST /api/v1/mihomo/subscriptions)
	CreateMihomoSubscription(w http.ResponseWriter, r *http.Request)
	// DeleteMihomoSubscription Delete a subscription not referenced by an egress profile
	// (DELETE /api/v1/mihomo/subscriptions/{subscriptionId})
	DeleteMihomoSubscription(w http.ResponseWriter, r *http.Request, subscriptionId string)
	// UpdateMihomoSubscription Update subscription metadata and optionally replace its secret URL
	// (PUT /api/v1/mihomo/subscriptions/{subscriptionId})
	UpdateMihomoSubscription(w http.ResponseWriter, r *http.Request, subscriptionId string)
	// ListMihomoSubscriptionNodes List non-secret node summaries
	// (GET /api/v1/mihomo/subscriptions/{subscriptionId}/nodes)
	ListMihomoSubscriptionNodes(w http.ResponseWriter, r *http.Request, subscriptionId string)
	// RefreshMihomoSubscription Fetch and summarize one encrypted subscription
	// (POST /api/v1/mihomo/subscriptions/{subscriptionId}/refresh)
	RefreshMihomoSubscription(w http.ResponseWriter, r *http.Request, subscriptionId string)
	// SelectMihomoSubscription Revalidate and select this artifact for the next start or restart without managing the process
	// (POST /api/v1/mihomo/subscriptions/{subscriptionId}/select)
	SelectMihomoSubscription(w http.ResponseWriter, r *http.Request, subscriptionId string)
	// ListModemCandidates Scan and list currently discovered modems that have not been added
	// (GET /api/v1/modem-candidates)
	ListModemCandidates(w http.ResponseWriter, r *http.Request)
	// ListManagedModems List administrator-added modems and their current observed state
	// (GET /api/v1/modems)
	ListManagedModems(w http.ResponseWriter, r *http.Request)
	// AddManagedModem Add one currently discovered modem without changing hardware state
	// (POST /api/v1/modems)
	AddManagedModem(w http.ResponseWriter, r *http.Request)
	// ReadManagedModemEquipmentIdentity Read one online managed modem's IMEI on explicit administrator request
	// (POST /api/v1/modems/{modemId}/equipment-identity)
	ReadManagedModemEquipmentIdentity(w http.ResponseWriter, r *http.Request, modemId string)
	// SetManagedModemRFState Set one managed modem's runtime RF state through its typed adapter
	// (PUT /api/v1/modems/{modemId}/rf-state)
	SetManagedModemRFState(w http.ResponseWriter, r *http.Request, modemId string)
	// ListNotificationChannels List outbound notification channels without credentials
	// (GET /api/v1/notification-channels)
	ListNotificationChannels(w http.ResponseWriter, r *http.Request)
	// CreateNotificationChannel Store an encrypted WeCom or Feishu webhook
	// (POST /api/v1/notification-channels)
	CreateNotificationChannel(w http.ResponseWriter, r *http.Request)

	// (DELETE /api/v1/notification-channels/{channelId})
	DeleteNotificationChannel(w http.ResponseWriter, r *http.Request, channelId string)

	// (PUT /api/v1/notification-channels/{channelId})
	UpdateNotificationChannel(w http.ResponseWriter, r *http.Request, channelId string)
	// TestNotificationChannel Send one explicit test message
	// (POST /api/v1/notification-channels/{channelId}/test)
	TestNotificationChannel(w http.ResponseWriter, r *http.Request, channelId string)
	// PutSetupAdministrator Create or replace the sole administrator while first-run setup remains uninitialized
	// (PUT /api/v1/setup/administrator)
	PutSetupAdministrator(w http.ResponseWriter, r *http.Request)
	// ConsumeSetupBootstrap Exchange a one-time root-generated bootstrap code for a restricted setup session
	// (POST /api/v1/setup/bootstrap)
	ConsumeSetupBootstrap(w http.ResponseWriter, r *http.Request)
	// CompleteSetup Revalidate every setup prerequisite and atomically enter ready
	// (POST /api/v1/setup/complete)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// ConfirmSetupHardware Confirm the current read-only hardware inventory
	// (POST /api/v1/setup/hardware/confirm)
	ConfirmSetupHardware(w http.ResponseWriter, r *http.Request)
	// GetSetupHardwareTopology Read the RF-Off normalized hardware topology during first-run setup
	// (GET /api/v1/setup/hardware/topology)
	GetSetupHardwareTopology(w http.ResponseWriter, r *http.Request)
	// PutSetupHTTPS Configure loopback management or generate a local-CA HTTPS candidate
	// (PUT /api/v1/setup/https)
	PutSetupHTTPS(w http.ResponseWriter, r *http.Request)
	// ConfirmSetupHTTPS Confirm the displayed SHA-256 local root fingerprint
	// (POST /api/v1/setup/https/confirm)
	ConfirmSetupHTTPS(w http.ResponseWriter, r *http.Request)
	// GetSetupHTTPSRootCertificate Read the public local root certificate for explicit trust installation
	// (GET /api/v1/setup/https/root-certificate)
	GetSetupHTTPSRootCertificate(w http.ResponseWriter, r *http.Request)
	// GetSetupInventory Read the restricted HIL-0 inventory while the instance remains RF Off
	// (GET /api/v1/setup/inventory)
	GetSetupInventory(w http.ResponseWriter, r *http.Request)
	// GetSetupSession Resume the restricted first-run session from its HttpOnly cookie
	// (GET /api/v1/setup/session)
	GetSetupSession(w http.ResponseWriter, r *http.Request)
	// GetSetupStatus Read the first-run boundary without opening normal business APIs
	// (GET /api/v1/setup/status)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// PutSetupStorage Validate and persist the data and recording roots for a new instance
	// (PUT /api/v1/setup/storage)
	PutSetupStorage(w http.ResponseWriter, r *http.Request)
	// GetSystemHealth Read the local control-plane health snapshot
	// (GET /api/v1/system/health)
	GetSystemHealth(w http.ResponseWriter, r *http.Request)
	// ListVoWiFiLines List desired and observed Host VoWiFi state for current Lines
	// (GET /api/v1/vowifi-lines)
	ListVoWiFiLines(w http.ResponseWriter, r *http.Request)
	// ActivateVoWiFiLine Persist activation intent and start the fixed Host VoWiFi runtime
	// (POST /api/v1/vowifi-lines/{lineId}/activate)
	ActivateVoWiFiLine(w http.ResponseWriter, r *http.Request, lineId string)
	// DeactivateVoWiFiLine Persist deactivation intent and remove the Line runtime
	// (POST /api/v1/vowifi-lines/{lineId}/deactivate)
	DeactivateVoWiFiLine(w http.ResponseWriter, r *http.Request, lineId string)
}

